'website-development':()=>detail('Website development','Websites designed around your business goals.',[['Discovery','We learn your business, audience and goals before designing.'],['Design and build','Responsive pages with a clear structure and conversion-minded layout.'],['Review','You review progress and request changes in agreed rounds.'],['Quality checks','Testing across devices and browsers before launch.'],['Launch and handover','Your site goes live and we hand it over to you.']],['Business and startup websites','Professional landing pages','Custom website experiences','E-commerce, only where scope and requirements allow it','Basic SEO and performance foundations'],['Final deliverables, timelines and pricing are confirmed in writing before work starts.'],EXD),
