function draw(){
 let h=(location.hash||'#home').slice(1);if(h==='client-portal')h='portal';if(!R[h])h='home';window._mode=Object.keys(R).indexOf(h);
 document.documentElement.classList.remove('lamp-lit');app.classList.remove('out');app.innerHTML=R[h]();app.style.animation='none';void app.offsetWidth;app.style.animation='';document.querySelectorAll('nav a').forEach(a=>{const on=a.dataset.r===(h.indexOf('portal')===0?'portal':h);a.classList.toggle('on',on);on?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});
 $('#nav').classList.remove('open');$('#burger').setAttribute('aria-expanded','false');window.scrollTo(0,0);if(window._rt)app.focus({preventScroll:true});window._rt=1;
 const t=document.querySelector('.pagehead h1,.hero h1');document.title=(h==='home'?'':(t?t.textContent.trim().slice(0,40)+' — ':''))+'TRUE RYZE';{const md=document.querySelector('meta[name=description]');if(md&&DM[h])md.setAttribute('content',DM[h])}
 init();if(matchMedia('(prefers-reduced-motion:reduce)').matches&&window.__drawHands)window.__drawHands(0,true);
}
window.addEventListener('hashchange',route);addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#nav').classList.contains('open')){$('#nav').classList.remove('open');$('#burger').setAttribute('aria-expanded','false');$('#burger').focus()}});
$('#burger').onclick=e=>{const o=$('#nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',o)};

/* reveals, tilt, magnetic */
const rel=el=>setTimeout(()=>{el.classList.remove('rv','in');el.style.transitionDelay=''},900);
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');rel(e.target);io.unobserve(e.target)}}),{threshold:.12});
document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('[data-plan]');if(a)window._plan=a.dataset.plan});
function spk(card,n,cls){if(card.querySelector('.spk-layer'))return;const L=document.createElement('span');L.className='spk-layer '+(cls||'');L.setAttribute('aria-hidden','true');
 for(let i=0;i<n;i++){const s=document.createElement('i'),place=()=>{s.style.left=(6+Math.random()*88)+'%';s.style.top=(6+Math.random()*88)+'%';s.style.setProperty('--s',(8+Math.random()*10)+'px')};place();
  s.style.animationDuration=(2.4+Math.random()*2.6)+'s';s.style.animationDelay=(Math.random()*4)+'s';s.addEventListener('animationiteration',place);L.appendChild(s)}card.prepend(L)}
const vio=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('paused',!e.isIntersecting)),{rootMargin:'120px'});
const PIC=d=>'<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d+'</svg>';
