const profOK=u=>/^https:\/\/[^\s"'<>]+$/.test(u||'');
function profilesBlock(compact){return PROF.map(([k,n,ic])=>profOK(PROFILES[k])?`<a class="pf" href="${PROFILES[k]}" target="_blank" rel="noopener noreferrer" aria-label="${n}">${ic}<span>${n}</span></a>`:(compact?'':`<span class="pf off" aria-disabled="true">${ic}<span>${n}</span><em>Soon</em></span>`)).join('')}
function profilesCard(){const any=PROF.some(([k])=>profOK(PROFILES[k]));return `<div class="card trust"><h3>Find us online</h3><p>${any?'Find our location and follow our profiles.':'Our Google Maps location and social profiles will appear here as they go live.'}</p><div class="pfs">${profilesBlock(false)}</div></div>`}

