<div class="card dc span6 rv"><h3>Services &amp; pricing</h3><h4 class="sh">Monthly services</h4><ul class="lst">${c.monthly.map(([a,b])=>`<li><span>${a}</span><span>${b}</span></li>`).join('')}</ul><h4 class="sh">Past services</h4><ul class="lst">${c.past.map(([a,b])=>`<li><span>${a}</span><span>${b}</span></li>`).join('')}</ul><h4 class="sh">Pricing taken</h4><ul class="lst">${c.pricing.map(([a,b])=>`<li><span>${a}</span><span>${b}</span></li>`).join('')}</ul></div>
